parameters.text:
이 사진은 여행지에서 찍은 사진입니다. 어느 나라/도시인지 추측하고 여행 일정을 만들어주세요.

규칙:
1. 사진 속 랜드마크나 특징으로 나라와 도시를 추측한다.
2. 그 도시의 대표 관광지로 2~3일 여행 일정을 만든다.
3. 각 장소의 위도(lat)와 경도(lng)를 포함한다.
4. 반드시 아래 JSON 형식으로만 응답한다. 다른 설명은 붙이지 않는다.

응답 형식:
{
  "country": "프랑스",
  "city": "파리",
  "days": [
    {
      "day": 1,
      "places": [
        { "name": "에펠탑", "lat": 48.8584, "lng": 2.2945, "description": "파리의 상징", "time": "오전" }
      ]
    }
  ]
}

parameters.jsCode:
const item = $input.first().json;

let rawText = "";
if (item.content && Array.isArray(item.content)) {
  const textBlock = item.content.find((c) => c.type === "text");
  rawText = textBlock ? textBlock.text : "";
} else if (typeof item.text === "string") {
  rawText = item.text;
}

let cleaned = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();
const start = cleaned.indexOf("{");
const end = cleaned.lastIndexOf("}");
if (start !== -1 && end !== -1) {
  cleaned = cleaned.substring(start, end + 1);
}

try {
  const parsed = JSON.parse(cleaned);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { country: "", city: "", days: [], error: "파싱 실패", raw: cleaned } }];
}

const item = $input.first().json;

// content 배열에서 text 블록만 추출
let rawText = "";
if (item.content && Array.isArray(item.content)) {
  const textBlock = item.content.find((c) => c.type === "text");
  rawText = textBlock ? textBlock.text : "";
} else if (typeof item.text === "string") {
  rawText = item.text;
}

// 코드블록만 제거 (다른 정리는 일단 하지 않음)
let cleaned = rawText
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// 첫 '{' 부터 마지막 '}' 까지만
const start = cleaned.indexOf("{");
const end = cleaned.lastIndexOf("}");
if (start !== -1 && end !== -1) {
  cleaned = cleaned.substring(start, end + 1);
}

let menu = [];
let debugInfo = "";
try {
  const parsed = JSON.parse(cleaned);
  menu = Array.isArray(parsed.menu) ? parsed.menu : [];
} catch (e) {
  // 실패 시 정확한 에러 메시지와 처리 대상 텍스트를 그대로 반환
  return [
    {
      json: {
        menu: [],
        count: 0,
        error: e.message,           // 진짜 에러 이유
        parseTarget: cleaned,       // 파싱하려던 실제 문자열
        rawType: typeof rawText,    // rawText 타입 확인
      },
    },
  ];
}

return [{ json: { menu: menu, count: menu.length } }];
